assert.ok(!fs.existsSync(OUT),'Fresh immutable evidence folder required');fs.mkdirSync(OUT,{recursive:true});fs.copyFileSync(__filename,OUT+'/executed-helper.cjs');fs.copyFileSync(__dirname+'/round1-consumer-disagreement-matrix.json',OUT+'/round1-consumer-disagreement-matrix.json');const save=()=>fs.writeFileSync(OUT+'/results.json',JSON.stringify(report,null,2)+'\n');save();
const P=id=>`[data-page="${id}"]`,books=['current.json','team-details.json','matchup-breakdown.json','player-history.json'];let browser;
async function ready(page,id){await page.waitForFunction(v=>document.querySelector('.page.active')?.dataset.page===v,id,{timeout:30000});await page.waitForFunction(()=>document.documentElement.dataset.dataReady==='true'&&window.PD_DATA?.roster?.length,null,{timeout:30000});await page.evaluate(async()=>document.fonts.ready);await page.waitForFunction(()=>[...document.querySelectorAll('.page.active img')].filter(i=>i.checkVisibility()).every(i=>i.complete&&i.naturalWidth>0),null,{timeout:30000});assert.equal(await page.locator('.page:visible').count(),1);}
async function go(page,id){const response=await page.goto(base+'#'+id,{waitUntil:'networkidle',timeout:45000});if(response)assert.equal(response.status(),200);else assert.ok(page.url().startsWith(base),'Same-document hash navigation retains actual served app origin/subpath');const pageid=id.startsWith('team/')?'team-details':id.startsWith('matchup/')?'matchup-breakdown':id.startsWith('game-report')?'game-report':id;await ready(page,pageid);return pageid;}
async function tap(page,r,selector,label){const locator=page.locator(selector).first();await locator.scrollIntoViewIfNeeded();if(r.viewport.width<500)await locator.tap();else await locator.click();r.actions.push({label:label||selector,selector,at:new Date().toISOString(),hash:new URL(page.url()).hash});save();}
async function select(page,r,selector,value){await page.locator(selector).selectOption(String(value));r.actions.push({label:'select',selector,value,at:new Date().toISOString(),hash:new URL(page.url()).hash});save();}
async function capture(page,r,label,anchor){if(anchor)await page.locator(anchor).first().scrollIntoViewIfNeeded();const native=await paint.capture(page,OUT,label),g=await geometry(page),shot={...native,geometry:g,untouchedNativeViewport:true};r.originals.push(shot);save();return shot;}
async function geometry(page){const g=await page.evaluate(()=>{const p=document.querySelector('.page.active'),s=p?.querySelector('.page-scroll')||p,b=e=>{const r=e.getBoundingClientRect();return{x:r.x,y:r.y,width:r.width,height:r.height,right:r.right,bottom:r.bottom};};return{page:p?.dataset.page,viewport:{width:innerWidth,height:innerHeight},documentWidth:document.documentElement.scrollWidth,frame:b(p),scroller:{...b(s),width:s.scrollWidth,client:s.clientWidth,top:s.scrollTop,height:s.scrollHeight,clientHeight:s.clientHeight},images:[...p.querySelectorAll('img')].filter(i=>i.checkVisibility()).map(i=>({src:i.currentSrc,natural:[i.naturalWidth,i.naturalHeight],fit:getComputedStyle(i).objectFit,...b(i)})),panels:[...p.querySelectorAll('.gr-brand,.gr-breadcrumb,.gr-hero,.gr-tabs,.gr-snapshot,.gr-comparison,.gr-performance,.gr-scoring,.gr-ancillary,.gr-bottom-nav,.gr-footer')].filter(e=>e.checkVisibility()).map(e=>({class:e.className,padding:getComputedStyle(e).padding,borderWidth:getComputedStyle(e).borderWidth,lineHeight:getComputedStyle(e).lineHeight,margin:getComputedStyle(e).margin,...b(e)})),headings:[...p.querySelectorAll('h1,h2,h3,.gr-brand p')].filter(e=>e.checkVisibility()).map(e=>({text:e.innerText,font:getComputedStyle(e).font,client:e.clientWidth,scroll:e.scrollWidth,...b(e)})),tables:[...p.querySelectorAll('table,.stand-row,.gr-table,.gr-player-row')].filter(e=>e.checkVisibility()).map(e=>({text:e.innerText.slice(0,150),...b(e)})),controls:[...p.querySelectorAll('button,select,a[href],summary')].filter(e=>e.checkVisibility()).map(e=>({text:e.innerText||e.getAttribute('aria-label'),disabled:!!e.disabled,attrs:Object.fromEntries([...e.attributes].filter(a=>a.name.startsWith('data-')||a.name.startsWith('aria-')).map(a=>[a.name,a.value])),...b(e)})),clipped:[...p.querySelectorAll('h1,h2,h3,th,td,.gr-player-name')].filter(e=>e.checkVisibility()&&e.scrollWidth>e.clientWidth+1).map(e=>({tag:e.tagName,text:e.innerText,width:e.clientWidth,scroll:e.scrollWidth}))};});assert.ok(g.documentWidth<=g.viewport.width+1,'No document horizontal overflow '+g.page);assert.ok(g.scroller.width<=g.scroller.client+1,'No internal horizontal overflow '+g.page);for(const t of g.tables)assert.ok(t.x>=g.frame.x-1&&t.right<=g.frame.right+1,'Table fits actual framed page '+t.text);for(const c of g.controls)assert.ok(c.x>=g.frame.x-1&&c.right<=g.frame.right+1,'Control fits actual framed page '+c.text);assert.ok(g.images.every(i=>i.natural[0]>0&&i.natural[1]>0),'Visible real images decode');return g;}
async function inventory(page,id){return page.locator(P(id)).evaluate(p=>[...p.querySelectorAll('button,select,a[href],summary')].filter(e=>e.checkVisibility()).map(e=>({tag:e.tagName,text:e.innerText,disabled:!!e.disabled,attrs:Object.fromEntries([...e.attributes].map(a=>[a.name,a.value])),options:e.options?[...e.options].map(o=>({value:o.value,text:o.text})):undefined})));}
async function closeDialog(page,r){const d=page.locator('dialog[open]').first();if(!await d.count())return;const close=d.locator('.dialog-close,[data-gr-action="close"],[aria-label*="Close"],button').filter({hasText:/close|×/i}).first();if(await close.count())await close.click();else await page.keyboard.press('Escape');await d.waitFor({state:'hidden'});r.actions.push({label:'native-dialog-close'});save();}
async function stage(page,r,name,task){const row={name,status:'running',startedAt:new Date().toISOString()};r.stages.push(row);save();try{row.result=await task();row.status='passed';}catch(e){row.status='failed';row.failure={message:e.message,stack:e.stack};console.log(JSON.stringify({stage:name,status:'failed',message:e.message}));await closeDialog(page,r).catch(()=>{});}finally{row.completedAt=new Date().toISOString();save();}}
async function snapshotProof(page){const result=await page.evaluate(async()=>{const objects={current:window.PD_DATA,team:window.PDTeamDetails?.getRawDataset?.()||window.PDTeamDetails?.getDataset?.(),matchup:window.MatchupBreakdown?.getRawDataset?.()||window.MatchupBreakdown?.getDataset?.(),report:window.PDGameReport?.getDataset?.()||window.GameReport?.getDataset?.()};const rows={};for(const[key,value]of Object.entries(objects)){if(!value)continue;const bytes=new TextEncoder().encode(JSON.stringify(value));rows[key]={retrievedAt:value.retrievedAt,season:value.season,sha256:[...new Uint8Array(await crypto.subtle.digest('SHA-256',bytes))].map(v=>v.toString(16).padStart(2,'0')).join(''),bytes:bytes.length};}return rows;});for(const[key,file]of [['current','current.json'],['team','team-details.json'],['matchup','matchup-breakdown.json']])if(result[key])assert.equal(result[key].sha256,SHA(Buffer.from(JSON.stringify(JSON.parse(fs.readFileSync(ROOT+'/assets/data/'+file))))),'Loaded real '+key+' data equals original source');return result;}
async function served(page){const rows=await page.evaluate(async expected=>{const names=Object.keys(expected),out=[];for(let i=0;i<names.length;i+=6)out.push(...await Promise.all(names.slice(i,i+6).map(async file=>{const response=await fetch(file,{cache:'no-store'}),bytes=await response.arrayBuffer();return{file,status:response.status,bytes:bytes.byteLength,sha256:[...new Uint8Array(await crypto.subtle.digest('SHA-256',bytes))].map(v=>v.toString(16).padStart(2,'0')).join('')};})));return out;},source);for(const row of rows){assert.equal(row.status,200,'Actual exact runtime HTTP200 '+row.file);assert.equal(row.sha256,source[row.file],'Actual runtime body matches frozen source '+row.file);}return rows;}
async function home(page,r){await go(page,'home');for(const sport of ['nfl','nba','nrl','ufc']){await tap(page,r,P('home')+` [data-home-select="${sport}"]`);assert.equal(await page.locator(P('home')).getAttribute('data-home-sport'),sport);assert.equal(await page.locator(P('home')+' [data-home-entry]').isDisabled(),sport!=='nfl');await ready(page,'home');await geometry(page);}await tap(page,r,P('home')+' [data-home-select="nfl"]');await capture(page,r,'home-'+r.viewport.width);await tap(page,r,P('home')+' [data-home-entry]','Home→NFL');await ready(page,'nfl');r.consumerResourcesBeforeExplicitAudit=await page.evaluate(()=>performance.getEntriesByType('resource').map(e=>({url:e.name,decodedBodySize:e.decodedBodySize,encodedBodySize:e.encodedBodySize,transferSize:e.transferSize,duration:e.duration,initiatorType:e.initiatorType})));r.consumerResourceQualification='Natural Home/sport/NFL consumer requests captured before explicit whole-runtime verification fetch; auditing all assets is not product load behavior.';return{source:'Existing Home untouched',geometry:await geometry(page)};}
async function standingsProof(page,r){const state=await page.evaluate(()=>{const s=window.PDApp.getContext().state;return{week:s.week,conference:s.conference,division:s.nflDivision,sort:s.nflSort,form:s.nflForm};}),value=await nflValues.rows(page,JSON.parse(fs.readFileSync(ROOT+'/assets/data/current.json')),state.week,state.conference,state.division,state.sort,state.form);(r.standingsValues||=[]).push(value);save();return value;}
async function dashboard(page,r){await go(page,'nfl');await capture(page,r,'nfl-'+r.viewport.width);for(const conf of ['NFC','AFC']){await tap(page,r,P('nfl')+` [data-conference="${conf}"]`);assert.equal(await page.locator(P('nfl')+` [data-conference="${conf}"]`).getAttribute('aria-pressed'),'true');await geometry(page);await standingsProof(page,r);}for(const id of ['#division-select','#form-select','#standings-sort','#week-select']){const values=await page.locator(id).evaluate(e=>[...e.options].map(o=>o.value));for(const value of [...new Set([values[0],values.at(-1)])]){await select(page,r,id,value);assert.equal(await page.locator(id).inputValue(),value);await geometry(page);await standingsProof(page,r);}}for(const tab of ['players','recap','ladder']){await tap(page,r,P('nfl')+` [data-nfl-tab="${tab}"]`);assert.equal(await page.locator(P('nfl')+` [data-nfl-tab="${tab}"]`).getAttribute('aria-selected'),'true');}await select(page,r,'#week-select',await page.evaluate(()=>String(window.PD_DATA.currentWeek)));await tap(page,r,P('nfl')+' [data-nfl-tab="recap"]');const recap=page.locator(P('nfl')+' [data-nfl-action="report"]').first();if(await recap.count()){const event=await recap.getAttribute('data-game');await tap(page,r,P('nfl')+' [data-nfl-action="report"]','Weekly recap→exact completed report');await ready(page,'game-report');assert.equal(new URLSearchParams(new URL(page.url()).hash.split('?')[1]).get('game'),event);await page.goBack();await ready(page,'nfl');r.actions.push({label:'native-browser-back-report-to-NFL'});}await tap(page,r,P('nfl')+' [data-nfl-tab="ladder"]');for(const action of ['teams','insights','more','matchups']){await tap(page,r,P('nfl')+` [data-nfl-action="${action}"]`);const actual=await page.locator('.page.active').getAttribute('data-page');if(actual==='nfl'&&await page.locator(P('nfl')+' [data-nfl-action="close-preview"]').count())await tap(page,r,P('nfl')+' [data-nfl-action="close-preview"]');else await go(page,'nfl');}for(const position of ['QB','RB','WR']){const s=P('nfl')+` [data-nfl-action="leaders"][data-position="${position}"]`;if(await page.locator(s).count()){await tap(page,r,s);assert.equal(await page.locator(s).first().getAttribute('aria-expanded'),'true');await tap(page,r,s);}}await select(page,r,'#week-select',await page.evaluate(()=>String(window.PD_DATA.currentWeek)));await tap(page,r,P('nfl')+' [data-conference="NFC"]');await select(page,r,'#division-select','all');await tap(page,r,P('nfl')+' [data-standings-toggle]');const dal=page.locator(P('nfl')+' [data-nfl-action="team"][data-team="DAL"]');if(await dal.count()){await tap(page,r,P('nfl')+' [data-nfl-action="team"][data-team="DAL"]');await tap(page,r,P('nfl')+' [data-nfl-action="team-details"][data-team="DAL"]','NFL ladder→Dallas');await ready(page,'team-details');}else await go(page,'team/DAL');return{inventory:await inventory(page,'team-details'),loaded:await snapshotProof(page)};}
async function teamDetails(page,r){await go(page,'team/DAL');await team.ready(page);await capture(page,r,'team-dallas-'+r.viewport.width);for(const[id,values]of [['#team-window-select',['3','10','5']],['#team-season-select',['current','cross']],['#team-venue-select',['home','away','neutral','all']]])for(const value of values){await select(page,r,id,value);assert.equal(await page.locator(id).inputValue(),value);await geometry(page);}for(const mode of ['total','average'])await tap(page,r,P('team-details')+` [data-td-mode="${mode}"]`);for(const action of ['venues','schedule','sources']){await tap(page,r,P('team-details')+` [data-td-action="${action}"]`);await page.locator('#team-details-dialog[open]').waitFor();await closeDialog(page,r);}for(const tab of ['players','lineup','form']){await tap(page,r,P('team-details')+` [data-team-tab="${tab}"]`);assert.equal(await page.locator(P('team-details')+` [data-team-tab="${tab}"]`).getAttribute('aria-selected'),'true');await geometry(page);}const first=page.locator(P('team-details')+' [data-team-game]').first(),game=await first.getAttribute('data-team-game');if(await first.getAttribute('aria-expanded')!=='true')await tap(page,r,P('team-details')+` [data-team-game="${game}"]`);await tap(page,r,P('team-details')+` [data-td-action="report"][data-game="${game}"]`,'Dallas completed game→Game Report');await ready(page,'game-report');return{game,hash:new URL(page.url()).hash,loaded:await snapshotProof(page)};}
async function matchup(page,r){await go(page,'matchup/DAL');await mb.ready(page);await capture(page,r,'matchup-'+r.viewport.width);for(const tab of ['form','lineup','players']){await tap(page,r,P('matchup-breakdown')+` [data-mb-tab="${tab}"]`);assert.equal(await page.locator(P('matchup-breakdown')+` [data-mb-tab="${tab}"]`).getAttribute('aria-selected'),'true');await geometry(page);}for(const[id,values]of [['#matchup-window-select',['3','10','5']],['#matchup-season-select',['current','cross']],['#matchup-venue-select',['home','away','neutral','all']]])for(const value of values){await select(page,r,id,value);assert.equal(await page.locator(id).inputValue(),value);}for(const action of ['sources','schedule','qb-status']){const s=P('matchup-breakdown')+` [data-mb-action="${action}"]`;if(await page.locator(s).count()){await tap(page,r,s);await page.locator('#matchup-breakdown-dialog[open]').waitFor();await closeDialog(page,r);}}for(const qb of ['last5','opponent','pressure','venue'])await tap(page,r,P('matchup-breakdown')+` [data-mb-qb="${qb}"]`);await tap(page,r,P('matchup-breakdown')+' [data-mb-tab="form"]');const reportButton=page.locator(P('matchup-breakdown')+' [data-mb-action="report"]').first();if(await reportButton.count()){const game=await reportButton.getAttribute('data-mb-game');await tap(page,r,P('matchup-breakdown')+' [data-mb-action="report"]','Matchup form→Game Report');await ready(page,'game-report');return{game,reportHash:new URL(page.url()).hash};}return{missingCompletedReport:true};}
async function steelers(page,r){await go(page,'steelers');for(const tab of ['schedule','stats','matchups','roster']){await tap(page,r,P('steelers')+` [data-team-tab="${tab}"]`);await geometry(page);}for(const filter of ['QB','RB','WR','TE','ALL']){const s=P('steelers')+` [data-filter="${filter}"]`;if(await page.locator(s).count())await tap(page,r,s);}const players=page.locator(P('steelers')+' [data-player]');assert.ok(await players.count()>0);await tap(page,r,P('steelers')+' [data-player]','Player card→research');await page.waitForFunction(()=>document.querySelector('[data-player-history-state="ready"]'),null,{timeout:30000});for(const mode of ['opponent','recent'])await tap(page,r,P('steelers')+` [data-history-mode="${mode}"]`);const breakdown=page.locator(P('steelers')+' .game-breakdown > summary').first();if(await breakdown.count())await tap(page,r,P('steelers')+' .game-breakdown > summary');await capture(page,r,'steelers-research-'+r.viewport.width);return{loaded:await snapshotProof(page),inventory:await inventory(page,'steelers')};}
async function reportReady(page){await ready(page,'game-report');await page.waitForFunction(()=>document.documentElement.dataset.gameReportDataReady==='true'&&window.PDGameReport?.getReport?.()&&document.querySelector('.page.active .gr-quarter-table'),null,{timeout:30000});await ready(page,'game-report');}
async function reportValues(page,r){await reportReady(page);const state=await page.evaluate(()=>window.PDGameReport.getState()),idx=JSON.parse(fs.readFileSync(ROOT+'/assets/data/game-reports.json')),meta=idx.games[state.game];assert.ok(meta,'Routed game belongs to verified source index');const raw=fs.readFileSync(ROOT+'/'+meta.detailUrl),game=JSON.parse(raw);assert.equal(SHA(raw),meta.sha256,'Original selected report obeys index checksum');const loaded=await page.evaluate(async()=>{const hashes={};for(const[key,value]of Object.entries({index:window.PDGameReport.getDataset(),detail:window.PDGameReport.getReport()})){const bytes=new TextEncoder().encode(JSON.stringify(value));hashes[key]=[...new Uint8Array(await crypto.subtle.digest('SHA-256',bytes))].map(n=>n.toString(16).padStart(2,'0')).join('');}return hashes;});assert.equal(loaded.index,SHA(Buffer.from(JSON.stringify(idx))),'Actual loaded report index matches original');assert.equal(loaded.detail,SHA(Buffer.from(JSON.stringify(game))),'Actual loaded report detail matches original');const sides=[state.team,game.home_team===state.team?game.away_team:game.home_team],score=t=>t===game.home_team?game.home_score:game.away_score,fmt=v=>v===null||v===undefined||v===''?'—':Number(v).toLocaleString('en-AU');const actual=await page.locator(P('game-report')+' .gr-quarter-table tbody tr').evaluateAll(rows=>rows.map(row=>({team:row.querySelector('th').innerText.trim(),values:[...row.querySelectorAll('td')].map(v=>v.innerText.trim())})));for(let n=0;n<sides.length;n++){assert.equal(actual[n].team,game.providerTeamAbbreviations?.[sides[n]]||sides[n]);const qs=game.quarters[sides[n]]||[],len=Math.max(4,...Object.values(game.quarters).map(q=>q.length));assert.deepEqual(actual[n].values,[...Array.from({length:len},(_,i)=>fmt(qs[i])),fmt(score(sides[n]))],'Real quarter cells and totals match exact selected-game source');if(qs.length&&qs.every(v=>v!==null))assert.equal(qs.reduce((a,b)=>a+b,0),score(sides[n]),'Quarter arithmetic agrees with final score');}const own=await page.locator(P('game-report')+' .gr-score-own').innerText(),other=await page.locator(P('game-report')+' .gr-score-other').innerText();assert.equal(own,fmt(score(sides[0])));assert.equal(other,fmt(score(sides[1])));if(state.tab==='overview'||state.tab==='box-score'){const values=await page.locator(P('game-report')+' [data-gr-stat]').evaluateAll(es=>es.map(e=>({team:e.dataset.grTeam,key:e.dataset.grStat,value:e.innerText})));for(const v of values){const st=game.stats[v.team],expected=v.key==='thirdDown'?st.thirdDownMade!=null&&st.thirdDownAttempts!=null?`${fmt(st.thirdDownMade)}/${fmt(st.thirdDownAttempts)}`:'—':v.key==='penalties'?st.penalties!=null&&st.penaltyYards!=null?`${fmt(st.penalties)}–${fmt(st.penaltyYards)}`:'—':v.key==='possession'?st.possession||'—':fmt(st[v.key]);assert.equal(v.value,expected,'Actual team-comparison field '+v.team+'/'+v.key);}if(state.tab==='overview'){const cum=await page.locator(P('game-report')+' .gr-cumulative').evaluateAll(es=>es.map(e=>[...e.querySelectorAll('b')].map(v=>v.innerText))),counts=[1,2,3,null];for(let i=0;i<counts.length;i++)for(let n=0;n<sides.length;n++){const qs=game.quarters[sides[n]],count=counts[i],value=count?qs.length>=count&&qs.slice(0,count).every(v=>v!==null)?qs.slice(0,count).reduce((a,b)=>a+b,0):null:score(sides[n]);assert.equal(cum[i][n],fmt(value),'Cumulative quarter card matches original source');}}}const g=await geometry(page);assert.deepEqual(g.clipped,[],'New report headings and table cells fit, without intrinsic text clipping');const proof={game:game.id,meta,state,loaded,quarterCells:actual,geometry:g};(r.reportValues||=[]).push(proof);save();return{game,state,sides,proof};}
async function playerValueProof(page,r,game,state){const actual=await page.locator(P('game-report')+' button[data-gr-player]').evaluateAll(es=>es.map(e=>({id:e.dataset.grPlayer,name:e.querySelector('.gr-player-identity strong').innerText,values:[...e.querySelectorAll(':scope > b')].map(v=>v.innerText)}))),rows=game.players[state.performanceTeam]||[],keys={passing:['completionAttempt','passingYards','passingTD','interceptions'],rushing:['rushingAttempts','rushingYards','rushingAverage','rushingTD'],receiving:['receptions','receivingYards','targets','receivingTD']}[state.kind],fmt=(v,p=0)=>v===null||v===undefined||v===''?'—':Number(v).toLocaleString('en-AU',{maximumFractionDigits:p});let prior=Infinity;for(const row of actual){const player=rows.find(p=>String(p.id)===row.id);assert.ok(player,'Player row is exact selected-game participant, not current roster substitution');assert.equal(row.name,player.name);const expected=keys.map(key=>key==='completionAttempt'?player.stats.completions!=null&&player.stats.passingAttempts!=null?`${fmt(player.stats.completions)}/${fmt(player.stats.passingAttempts)}`:'—':key==='rushingAverage'?player.stats.rushingYards!=null&&player.stats.rushingAttempts>0?fmt(player.stats.rushingYards/player.stats.rushingAttempts,1):'—':fmt(player.stats[key]));assert.deepEqual(row.values,expected,'All displayed category stats agree with real per-game row');const yards=player.stats[{passing:'passingYards',rushing:'rushingYards',receiving:'receivingYards'}[state.kind]];if(yards!==null&&yards!==undefined){assert.ok(yards<=prior,'Player yardage order descending');prior=yards;}}const result={team:state.performanceTeam,kind:state.kind,actual};(r.playerValueProofs||=[]).push(result);save();return result;}
async function sourceIntegrityNative(page,r){const matrixPath=__dirname+'/round1-consumer-disagreement-matrix.json',matrix=JSON.parse(fs.readFileSync(matrixPath));await go(page,'team/CLE?tab=form&window=5&season=current&venue=all&mode=average');await go(page,'matchup/LV?tab=players&window=5&season=current&venue=all&mode=total&game=2026_03_LV_NO');await page.waitForFunction(()=>window.PDTeamDetails.getDataset()?._sourceIntegrity?.status==='verified'&&window.MatchupBreakdown.getDataset()?._sourceIntegrity?.status==='verified');const observations=await page.evaluate(issues=>{const effective={'team-details':window.PDTeamDetails.getDataset(),'matchup-breakdown':window.MatchupBreakdown.getDataset(),'player-history':window.PD_HISTORY},raw={'team-details':window.PDTeamDetails.getRawDataset(),'matchup-breakdown':window.MatchupBreakdown.getRawDataset(),'player-history':window.PD_HISTORY_RAW},at=(v,p)=>p.split(/[.\[\]]/).filter(Boolean).reduce((o,k)=>o?.[k],v);return issues.flatMap(issue=>issue.consumers.map(c=>({game:issue.gameId,field:issue.field,book:c.book,path:c.path,rawExpected:c.rawValue,rawActual:at(raw[c.book],c.path),effective:at(effective[c.book],c.path),neutralAlias:issue.field==='neutralSite'&&c.path.endsWith('.neutralSite')?at(effective[c.book],c.path.replace(/\.neutralSite$/,'.neutral')):undefined,derivedPath:c.derivedPath,derived:c.derivedPath?at(effective[c.book],c.derivedPath):undefined})));},matrix.disagreements);for(const o of observations){assert.deepEqual(o.rawActual,o.rawExpected,'Independently recorded original consumer cell remains intact '+o.path);if(o.path.endsWith('.homeAway'))assert.ok(o.effective===null||o.effective==='unknown','Conflicting venue classification is unavailable before filtering');else assert.equal(o.effective,null,'Known conflicting source cell is masked before derived aggregates '+o.path);if(o.field==='neutralSite'&&o.path.endsWith('.neutralSite'))assert.equal(o.neutralAlias,null,'Both neutral-site aliases are masked');if(o.derivedPath)assert.equal(o.derived,null,'Dependent share remains unavailable');}const native=[];for(const [club,side]of [['CLE','gained'],['NYJ','allowed']]){await go(page,`team/${club}?tab=form&window=5&season=current&venue=all&mode=average`);for(const mode of ['average','total']){await tap(page,r,P('team-details')+` [data-td-mode="${mode}"]`);for(const field of ['netPassing','totalOffense'])assert.equal((await page.locator(`[data-td-stat="${field}"][data-td-side="${side}"]`).innerText()).trim(),'—','Actual conflicting '+club+' '+side+' '+field+' '+mode+' never becomes a false numeric aggregate');assert.match(await page.locator(`[data-td-stat="rushing"][data-td-side="${side}"]`).innerText(),/\d/,'Independent rushing values remain available');}await tap(page,r,P('team-details')+' [data-td-action="sources"]');await page.locator('#team-details-dialog[open]').waitFor();const expectedIndex=JSON.parse(fs.readFileSync(ROOT+'/assets/data/game-reports.json'));for(const field of ['netPassing','totalOffense']){const issue=expectedIndex.knownDisagreements.find(i=>i.gameId==='2026_05_CLE_NYJ'&&i.field===field),actual=await page.locator(`#team-details-dialog [data-si-game="2026_05_CLE_NYJ"][data-si-field="${field}"]`).evaluateAll(ps=>ps.map(p=>({game:p.dataset.siGame,field:p.dataset.siField,readings:[...p.querySelectorAll('[data-si-reading-value]')].map(span=>({value:span.dataset.siReadingValue,text:span.innerText,links:[...span.querySelectorAll('a[data-si-source]')].map(a=>({id:a.dataset.siSource,value:a.dataset.siValue,retrievedAt:a.dataset.siRetrieved,url:a.href}))}))})));const binding={club,side,field,expected:issue,actual};(r.sourceProvenanceObservations||=[]).push(binding);save();assert.equal(actual.length,1,'Exactly one actual bound source-disagreement paragraph per field');assert.deepEqual(actual[0].readings.map(v=>v.value).sort(),issue.readings.map(v=>String(v.value)).sort(),'Both source values are actually displayed as separate bound readings');for(const reading of actual[0].readings){const expectedReading=issue.readings.find(v=>String(v.value)===reading.value);assert.ok(reading.text.trim().startsWith(reading.value),'Visible reading text displays its bound value');assert.deepEqual(reading.links.map(v=>v.id).sort(),[...expectedReading.sourceIds].sort(),'Each actual reading belongs only to its declared producer');for(const link of reading.links){const descriptor=issue.sources.find(v=>v.id===link.id);assert.equal(link.value,reading.value,'Actual source link retains the reading value association');assert.equal(link.url,descriptor.url,'Actual source URL is the exact producer source');assert.equal(link.retrievedAt,descriptor.retrievedAt,'Actual retrieval metadata is source exact');}}}await capture(page,r,'provenance-'+club+'-'+r.viewport.width);await closeDialog(page,r);native.push({club,side,modes:['average','total']});}await go(page,'matchup/LV?tab=players&window=5&season=current&venue=all&mode=total&game=2026_03_LV_NO');assert.equal((await page.locator('[data-mb-player-row="00-0039338"][data-mb-team="LV"][data-mb-kind="receiving"] [data-mb-field="targets"]').innerText()).trim(),'—','Actual source-conflicted receiver targets aggregate stays unavailable');await go(page,'matchup/ARI?tab=form&game=2024_17_ARI_LA');assert.match(await page.locator(P('matchup-breakdown')+' .mb-fixture-copy').innerText(),/Kickoff unavailable/i,'Actual conflicted fixture time stays unavailable');return{matrixSha256:SHA(fs.readFileSync(matrixPath)),rawPaths:observations,native,qualification:'The pre-adapter independently collected source-conflict matrix is retained; original payloads, consumer masks and actual aggregate UI are audited as separate layers.'};}
async function fullBoxProof(page,r,game){const fields={PASSING:['completionAttempt','passingYards','passingTD','interceptions'],RUSHING:['rushingAttempts','rushingYards','rushingAverage','rushingTD'],RECEIVING:['receptions','receivingYards','targets','receivingTD'],DEFENSIVE:['totalTackles','soloTackles','defensiveSacks','tacklesForLoss'],KICKING:['fieldGoalsMade','fieldGoalAttempts','extraPointsMade','kickingPoints'],PUNTING:['punts','puntYards','grossAvgPuntYards','puntsInside20'],'KICK RETURNS':['kickoffReturns','kickoffReturnYards','yardsPerKickoffReturn','kickoffReturnTD'],'PUNT RETURNS':['puntReturns','puntReturnYards','yardsPerPuntReturn','puntReturnTD'],FUMBLES:['fumbles','fumblesLost','fumblesRecovered'],INTERCEPTIONS:['defensiveInterceptions','interceptionReturnYards','interceptionTD']};const tables=await page.locator(P('game-report')+' .gr-box-team .gr-box-table').evaluateAll(tables=>tables.map(t=>({category:t.previousElementSibling.textContent.trim(),heading:[...t.querySelectorAll('thead th')].map(e=>e.textContent.trim()),rows:[...t.querySelectorAll('tbody tr')].map(tr=>({id:tr.querySelector('[data-player]')?.dataset.player,team:tr.querySelector('[data-player-team]')?.dataset.playerTeam,name:tr.querySelector('[data-player]')?.textContent.trim(),values:[...tr.querySelectorAll('td')].map(e=>e.textContent.trim())}))})));assert.equal(tables.length,20,'Every ten published full-box categories are rendered for both teams');const known=v=>v!==null&&v!==undefined&&v!==''&&Number.isFinite(Number(v)),fmt=v=>known(v)?Number(v).toLocaleString('en-AU',{maximumFractionDigits:1}):'—';let cells=0;for(const table of tables){assert.ok(fields[table.category],'Known independent statistical category '+table.category);for(const row of table.rows){if(!row.id){assert.match(row.values.join(' '),/unavailable/i);continue;}const player=game.players[row.team].find(p=>String(p.id)===row.id);assert.ok(player,'Every published box-score row identifies an actual source player');assert.equal(row.name,player.name);const stat=player.stats,values=fields[table.category].map(field=>field==='completionAttempt'?known(stat.completions)&&known(stat.passingAttempts)?fmt(stat.completions)+'/'+fmt(stat.passingAttempts):'—':field==='rushingAverage'?known(stat.rushingYards)&&known(stat.rushingAttempts)&&Number(stat.rushingAttempts)>0?fmt(Number(stat.rushingYards)/Number(stat.rushingAttempts)):'—':fmt(stat[field]));assert.deepEqual(row.values,values,'Every actual full-box statistical cell is exact source or explicit unavailable '+row.team+' '+row.id+' '+table.category);cells+=values.length;}}r.fullBoxCells={cells,categories:tables.map(t=>({category:t.category,rows:t.rows.filter(r=>r.id).length,representative:t.rows.find(r=>r.id)})),qualification:'Every rendered statistical cell is checked at every viewport, independently of the native profile input sampling split.'};save();return tables;}
